import api from "./axios";

export const gradeApi = {
  getAll: (params) => api.get("/grades", { params }),
  getByStudent: (studentId) => api.get(`/grades/student/${studentId}`),
  assign: (payload) => api.post("/grades/assign", payload),
  update: (id, payload) => api.put(`/grades/${id}`, payload),
  getGpa: (studentId) => api.get(`/grades/student/${studentId}/gpa`)
};
